function donorEsc(x){return String(x==null?"":x).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}
function donorPinPlace(pinId){
 try{if(typeof byId==="function"){const r=byId(pinId);if(r&&r.id)return r;}}catch(e){}
 return null;
}
